package com.lx.mc.foundation.cache;

import java.util.Collection;
import java.util.Map;
import java.util.Optional;

/**
 * 定义业务实体缓存的基础操作，使上层仓储不依赖具体缓存实现。
 *
 * <p>作者：lxcraftcm</p>
 * <p>创建时间：2026-07-31 13:04</p>
 *
 * <p>主要逻辑：</p>
 * <ol>
 *     <li>按照唯一标识读取、写入和删除缓存数据。</li>
 *     <li>提供只读快照和启动数据整体安装能力。</li>
 * </ol>
 *
 * <p>主要调用方：领域仓储的基础设施实现。</p>
 * <p>约束：业务服务不得绕过领域仓储直接操作本接口。</p>
 *
 * @param <K> 缓存键类型
 * @param <V> 缓存值类型
 */
public interface CacheStore<K, V> {

    /**
     * 按唯一标识查询缓存数据。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：读取指定键对应的当前缓存值。</p>
     * <p>主要调用方：领域仓储查询方法。</p>
     *
     * @param key 待查询的缓存键，不能为空
     * @return 包含缓存值的 Optional，不存在时返回空
     */
    Optional<V> find(K key);

    /**
     * 新增或替换指定缓存数据。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：使用给定值覆盖指定键的当前缓存内容。</p>
     * <p>主要调用方：领域仓储保存方法和启动数据安装流程。</p>
     * <p>副作用：修改当前进程中的缓存状态。</p>
     *
     * @param key   待写入的缓存键，不能为空
     * @param value 待写入的缓存值，不能为空
     */
    void put(K key, V value);

    /**
     * 删除指定缓存数据并返回删除前的值。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：移除指定键并封装原缓存值。</p>
     * <p>主要调用方：领域仓储删除方法。</p>
     * <p>副作用：修改当前进程中的缓存状态。</p>
     *
     * @param key 待删除的缓存键，不能为空
     * @return 包含删除前缓存值的 Optional，不存在时返回空
     */
    Optional<V> remove(K key);

    /**
     * 获取当前全部缓存值的只读快照。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：复制当前缓存值，避免调用方修改缓存内部集合。</p>
     * <p>主要调用方：领域仓储批量查询和停服刷盘流程。</p>
     *
     * @return 与调用时缓存状态对应的只读集合快照
     */
    Collection<V> snapshot();

    /**
     * 使用一组完整数据替换当前缓存内容。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：先校验启动数据，再清空并整体安装新数据。</p>
     * <p>主要调用方：插件启动数据加载流程。</p>
     * <p>副作用：替换当前进程中的全部缓存状态。</p>
     *
     * @param values 需要安装的完整键值集合，不能为空且不能包含空键或空值
     */
    void replaceAll(Map<K, V> values);

    /**
     * 清空当前缓存中的全部数据。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：移除缓存持有的全部键值。</p>
     * <p>主要调用方：插件关闭和测试清理流程。</p>
     * <p>副作用：清空当前进程中的缓存状态。</p>
     */
    void clear();

    /**
     * 获取当前缓存实体数量。
     *
     * <p>作者：lxcraftcm</p>
     * <p>创建时间：2026-07-31 13:04</p>
     * <p>主要逻辑：返回缓存内部键值数量。</p>
     * <p>主要调用方：状态监控和测试断言。</p>
     *
     * @return 当前缓存实体数量
     */
    int size();
}
